/** Real protocol state/ledger SQL; outbound legacy publication is deliberately not claimed by this fixture. */
class AgentGovernedExecutionStateTests extends AgentProtocolTransactionTests {
    AgentGovernedExecutionService engine;AgentProtocolResultService results;AgentProtocolAccess access;
    AgentProtocolPublicationService publication;AtomicReference<AgentProtocolAccess.Actor> current=new AtomicReference<>();
    Map<String,Object> contract;
    @BeforeEach void stateFixture(){
        access=mock(AgentProtocolAccess.class);current.set(actor);when(access.actor(eq("org"),anyBoolean())).thenAnswer(call->current.get());when(access.sessionActor(eq("org"),anyBoolean())).thenAnswer(call->current.get());
        var config=mock(AgentSessionProtocolConfiguration.class);when(config.number("lease-seconds")).thenReturn(60L);
        var provider=mock(ObjectProvider.class);publication=mock(AgentProtocolPublicationService.class);results=new AgentProtocolResultService(jdbc,store,access,evidence);ReflectionTestUtils.setField(results,"publication",publication);when(provider.getObject()).thenReturn(results);
        engine=new AgentGovernedExecutionService(jdbc,store,access,config,mock(AgentStructuredContractService.class),mock(AgentKnowledgeService.class),mock(AgentEnvironmentProfileService.class),evidence,provider,mock(AgentDirectExecutionService.class));
        ReflectionTestUtils.setField(engine,"policies",new AgentProtocolPolicyService(jdbc,store,access,config));
        ReflectionTestUtils.setField(engine,"taskLifecycle",new AgentProtocolTaskLifecycleService(jdbc,store));
        contract=new LinkedHashMap<>(Map.of("steps",List.of(Map.of("id","S1","sourcePosition",1)),"assertions",List.of(Map.of("id","A1","required",true),Map.of("id","A2","required",true)),"allowedActions",List.of("CREATE"),"dataRequirements",List.of(),"dependencies",List.of(),"authorUserId","author","authorPerson","author-person","outputs",Map.of()));
        var data=new LinkedHashMap<String,Object>();data.put("contract",contract);for(String key:List.of("actions","steps","knowledge","humanRequests"))data.put(key,new ArrayList<>());for(String key:List.of("variables","bindings","evidenceIdentities"))data.put(key,new LinkedHashMap<>());data.put("executorPersons",List.of("person"));data.put("executorIdentities",Map.of("user","person"));data.put("evidencePersons",List.of());
        var policy=Map.<String,Object>of("budget.calls",100,"budget.recoveries",2,"budget.recovery-seconds",30,"allowedActions",List.of("CREATE"),"actionRules",Map.of("CREATE",Map.of("effect","CREATE","entity","fixture")));
        jdbc.update("INSERT INTO msp_protocol_policy VALUES ('org','env',1,true,?)",store.payload(policy));jdbc.update("INSERT INTO msp_protocol_authorization VALUES ('PERSONAL','case',1,'org','env',?,?,?)".replace(",?,?,?)",",?,?)"),System.currentTimeMillis()+60000,store.payload(Map.of("allowedActions",List.of("CREATE"))));
        jdbc.update("INSERT INTO msp_protocol_session(id,organization_id,project_id,owner_id,agent_ref,source_type,source_id,environment_id,state,version,context_version,payload,create_time) VALUES ('session','org','project','user','agent','PERSONAL','case','env','OPEN',1,1,?,1)",store.payload(Map.of("maxPayloadBytes",100000,"responsibleUserId","responsible","authorization",Map.of("actionRules",Map.of("CREATE",Map.of("effect","CREATE","entity","fixture"))),"budget",Map.of("calls",100,"recoveries",2,"recoverySeconds",30))));
        jdbc.update("INSERT INTO msp_protocol_instance(id,session_id,case_id,phase,channel,verification,version,result_version,revision,generation,lease_owner,lease_until,calls_used,recoveries_used,recovery_ms,payload) VALUES ('instance','session','case','EXECUTING','OPEN','NONE',1,0,0,1,?,?,0,0,0,?)",actor.stableKey(),System.currentTimeMillis()+60000,store.payload(data));
        jdbc.execute("ALTER TABLE agent_case_evidence ADD COLUMN user_id VARCHAR(64)");jdbc.update("UPDATE agent_case_evidence SET user_id='uploader',protocol_instance_id='instance' WHERE id='personal'");
        jdbc.update("INSERT INTO msp_protocol_identity VALUES ('user','org','person',1,'fixture'),('author','org','author-person',1,'fixture'),('uploader','org','uploader-person',1,'fixture')");
    }
    Map<String,Object> request(){return new LinkedHashMap<>(Map.of("protocolVersion","1.0","idempotencyKey",UUID.randomUUID().toString(),"sessionId","session","caseExecutionId","instance","expectedContextVersion",jdbc.queryForObject("SELECT version FROM msp_protocol_instance WHERE id='instance'",Long.class),"leaseGeneration",jdbc.queryForObject("SELECT generation FROM msp_protocol_instance WHERE id='instance'",Long.class)));}
    Map<String,Object> call(String op,Map<String,Object> fields){var args=request();args.putAll(fields);if("action.prepare".equals(op))args.putIfAbsent("targetEntity","fixture");return engine.write(op,args);}
    Map<String,Object> data(){return store.data(jdbc.queryForMap("SELECT * FROM msp_protocol_instance WHERE id='instance'"));}
    void updateData(java.util.function.Consumer<Map<String,Object>> change){var data=data();change.accept(data);jdbc.update("UPDATE msp_protocol_instance SET payload=? WHERE id='instance'",store.payload(data));}
    @Test void preparedExternalActionBlocksRetryAndLeaseTakeoverMakesItUnknown(){
        var prepare=call("action.prepare",Map.of("actionType","CREATE","target","owned-object","parameters",Map.of(),"expectedEffect","one object","businessKey","fixture-key","queryMethod","authoritative lookup"));assertNotNull(prepare.get("actionId"));
        assertEquals("PROTOCOL_ACTION_UNKNOWN",assertThrows(MSException.class,()->call("action.prepare",Map.of("actionType","CREATE","target","owned-object","expectedEffect","one","businessKey","same","queryMethod","query"))).getMessage());
        call("lease.takeover",Map.of());assertEquals("UNKNOWN",AgentProtocolData.objects(data().get("actions")).getFirst().get("state"));assertEquals(2L,jdbc.queryForObject("SELECT generation FROM msp_protocol_instance",Long.class));
    }
    @Test void staleLeaseCannotCommitStepButRejectedLogicalCallIsCountedOnlyOnce(){
        var args=request();args.putAll(Map.of("leaseGeneration",0,"stepId","S1","observation","seen","outcome","SATISFIED","evidence",List.of()));
        assertEquals("PROTOCOL_LEASE_INVALID",assertThrows(MSException.class,()->engine.write("step.save",args)).getMessage());assertThrows(MSException.class,()->engine.write("step.save",args));
        assertEquals(1L,jdbc.queryForObject("SELECT calls_used FROM msp_protocol_instance",Long.class));assertTrue(AgentProtocolData.objects(data().get("steps")).isEmpty());
    }
    @Test void unresolvedObservationMustReferenceRealActionAndOriginalGeneration(){
        var args=new LinkedHashMap<String,Object>(Map.of("protocolVersion","1.0","idempotencyKey","observe","sessionId","session","caseExecutionId","instance","actionId","invented","originalGeneration",1,"observation","late"));
        assertEquals("PROTOCOL_ACTION_UNKNOWN",assertThrows(MSException.class,()->engine.write("observation.append",args)).getMessage());assertEquals(1L,jdbc.queryForObject("SELECT version FROM msp_protocol_instance",Long.class));
    }
    void submit(String result){call("case.finish",Map.of("result",result,"reason","fixture classification reason","assertions",List.of(Map.of("assertionId","A1","observation","first","evidence",List.of(Map.of("kind","PERSONAL","id","personal"))))));}
    Map<String,Object> reviewArgs(String fact1,String fact2){return new LinkedHashMap<>(Map.of("sessionId","session","caseExecutionId","instance","expectedResultVersion",1,"submissionRevision",1,"verificationAttemptId","attempt-1","assertions",List.of(decision("A1",fact1),decision("A2",fact2))));}
    Map<String,Object> decision(String id,String fact){return Map.of("assertionId",id,"fact",fact,"sufficient",!"UNKNOWN".equals(fact),"reason","authority inspected","authorityQuery","owned object fixture","queryTime",1,"evidence",List.of(Map.of("kind","PERSONAL","id","personal")));}
    Map<String,Object> applyReview(Map<String,Object> args){return store.transaction(()->{var i=jdbc.queryForMap("SELECT * FROM msp_protocol_instance WHERE id='instance' FOR UPDATE");var data=store.data(i);var result=results.apply("result.verify",args,jdbc.queryForMap("SELECT * FROM msp_protocol_session"),i,data,current.get(),"review-op");jdbc.update("UPDATE msp_protocol_instance SET verification=?,phase=?,payload=? WHERE id='instance'",i.get("verification"),i.get("phase"),store.payload(data));return result;});}
    void reviewer(){current.set(new AgentProtocolAccess.Actor("org","reviewer","HUMAN","independent-person",true));}
    @Test void confirmedDefectWithAnotherUnknownAssertionDoesNotBecomeFormalFail(){submit("FAIL");reviewer();var result=applyReview(reviewArgs("VIOLATED","UNKNOWN"));assertEquals("NEEDS_EVIDENCE",result.get("verification"));assertEquals(false,result.get("formalResultAccepted"));verifyNoInteractions(publication);assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM agent_case_submission",Integer.class));}
    @Test void submittedPassContradictedByCompleteFactsIsRejected(){submit("PASS");reviewer();assertEquals("REJECTED",applyReview(reviewArgs("VIOLATED","SATISFIED")).get("verification"));verifyNoInteractions(publication);}
    @Test void naturalPersonExclusionRejectsDifferentAccountOfExecutor(){submit("PASS");current.set(new AgentProtocolAccess.Actor("org","different-account","HUMAN","person",true));assertEquals("PROTOCOL_REVIEW_CONFLICT",assertThrows(MSException.class,()->applyReview(reviewArgs("SATISFIED","SATISFIED"))).getMessage());}
    @Test void legacyGateFailureKeepsSubmissionUnacceptedAndRetainsEvidence(){submit("PASS");reviewer();doThrow(new MSException("QUALITY_CASE_EVIDENCE_INVALID")).when(publication).validateCandidate(anyMap(),anyMap(),anyMap());assertEquals(false,applyReview(reviewArgs("SATISFIED","SATISFIED")).get("verificationAccepted"));assertNotEquals("ACCEPTED",jdbc.queryForObject("SELECT verification FROM msp_protocol_instance",String.class));assertFalse(evidence.cleanupPersonal(2)>0);}
    @Test void acceptedReviewDoesNotClaimFormalSyncAndContradictoryAttemptMarksDispute(){submit("PASS");reviewer();assertEquals(true,applyReview(reviewArgs("SATISFIED","SATISFIED")).get("verificationAccepted"));assertEquals("PENDING",data().get("syncStatus"));var conflict=reviewArgs("VIOLATED","SATISFIED");assertEquals(true,applyReview(conflict).get("conflictingAttempt"));assertEquals(true,data().get("disputed"));assertEquals("ACCEPTED",jdbc.queryForObject("SELECT verification FROM msp_protocol_instance",String.class));}

    void secondEvidence(){jdbc.update("INSERT INTO agent_case_evidence(id,project_id,case_id,expires_at,sha256,content_type,size_bytes,payload,user_id,protocol_instance_id) VALUES ('fresh','project','case',1,'new-hash','image/png',1,?,'uploader','instance')",new byte[]{2});}
    @Test void recoveryRequiresFreshEvidenceAndOneLogicalPermitDoesNotResetOnTakeover(){
        secondEvidence();var failure=call("step.save",Map.of("stepId","S1","observation","actual failure","outcome","VIOLATED","evidence",List.of(Map.of("kind","PERSONAL","id","personal"))));
        var retry=request();retry.putAll(Map.of("failureEventId",failure.get("eventId"),"observation","changed evidence","changedCondition","authority query now ready","proposedAction","retry original failed step","expectedObservation","same assertion","evidence",List.of(Map.of("kind","PERSONAL","id","fresh"))));
        var permit=engine.write("recovery.record",retry);engine.write("recovery.record",retry);assertEquals(1L,jdbc.queryForObject("SELECT recoveries_used FROM msp_protocol_instance",Long.class));assertEquals(1L,jdbc.queryForObject("SELECT recoveries_used FROM msp_protocol_session",Long.class));
        Long since=jdbc.queryForObject("SELECT recovery_since FROM msp_protocol_instance",Long.class);call("lease.takeover",Map.of());assertEquals(since,jdbc.queryForObject("SELECT recovery_since FROM msp_protocol_instance",Long.class));assertEquals(false,permit.get("replayed"));
    }
    @Test void sameFailureEvidenceCannotAuthorizeRecovery(){var failure=call("step.save",Map.of("stepId","S1","observation","failed","outcome","UNKNOWN","evidence",List.of(Map.of("kind","PERSONAL","id","personal"))));assertEquals("PROTOCOL_RECOVERY_REQUIRES_NEW_EVIDENCE",assertThrows(MSException.class,()->call("recovery.record",Map.of("failureEventId",failure.get("eventId"),"observation","same screenshot","changedCondition","claimed change","proposedAction","retry","expectedObservation","visible","evidence",List.of(Map.of("kind","PERSONAL","id","personal"))))).getMessage());assertEquals(0L,jdbc.queryForObject("SELECT recoveries_used FROM msp_protocol_instance",Long.class));}
    @Test void independentClassificationCanAcceptBlockedWithoutInventingReachedAssertions(){submit("BLOCKED");reviewer();var args=reviewArgs("UNKNOWN","UNKNOWN");args.put("classificationReview",Map.of("result","BLOCKED","decision","SUPPORTED","reason","credential missing verified independently","authorityQuery","credential state query","queryTime",1,"evidence",List.of(Map.of("kind","PERSONAL","id","personal"))));assertEquals(true,applyReview(args).get("verificationAccepted"));assertEquals("NOT_APPLICABLE",data().get("syncStatus"));verifyNoInteractions(publication);}
    @Test void passOutputsRequireSeparateIndependentEvidence(){updateData(value->{var declaration=AgentProtocolData.object(value.get("contract"));declaration.put("outputs",Map.of("count",Map.of("type","integer","required",true)));value.put("contract",declaration);});call("case.finish",Map.of("result","PASS","outputs",Map.of("count",2),"assertions",List.of(Map.of("assertionId","A1","observation","seen","evidence",List.of(Map.of("kind","PERSONAL","id","personal"))))));reviewer();assertThrows(MSException.class,()->applyReview(reviewArgs("SATISFIED","SATISFIED")));var args=reviewArgs("SATISFIED","SATISFIED");args.put("outputsReview",Map.of("outputsHash",AgentProtocolData.hash(Map.of("count",2)),"reason","count verified","authorityQuery","business query","queryTime",1,"evidence",List.of(Map.of("kind","PERSONAL","id","personal"))));assertEquals(true,applyReview(args).get("verificationAccepted"));}
    @Test void notRunCannotEraseAlreadyRecordedActions(){call("action.prepare",Map.of("actionType","CREATE","target","owned","expectedEffect","new object","businessKey","one","queryMethod","authority"));assertThrows(MSException.class,()->submit("NOT_RUN"));assertNull(jdbc.queryForObject("SELECT result FROM msp_protocol_instance",String.class));}
    @Test void resultSnapshotRetainsOriginalRevisionAfterSupplement(){submit("FAIL");var args=new LinkedHashMap<String,Object>(Map.of("protocolVersion","1.0","idempotencyKey","supplement","sessionId","session","caseExecutionId","instance","expectedResultVersion",1,"submissionRevision",1,"assertions",List.of(Map.of("assertionId","A2","observation","new observation","evidence",List.of(Map.of("kind","PERSONAL","id","personal"))))));engine.write("result.evidence.append",args);assertEquals(2,jdbc.queryForObject("SELECT COUNT(*) FROM msp_protocol_result_revision",Integer.class));var first=store.data(jdbc.queryForMap("SELECT payload FROM msp_protocol_result_revision WHERE result_version=1"));assertEquals(1,AgentProtocolData.objects(AgentProtocolData.object(first.get("data")).get("submittedAssertions")).size());}

    Map<String,Object> resolve(String operation,String action,String resolution){var args=request();args.remove("expectedContextVersion");args.remove("leaseGeneration");args.putAll(Map.of("actionId",action,"resolution",resolution,"queryEvidence","authoritative terminal lookup","evidence",List.of(Map.of("kind","PERSONAL","id","personal"))));if("CONFIRMED_EFFECT".equals(resolution))args.put("objectId","owned-object");else if("CONFIRMED_NO_EFFECT".equals(resolution))args.put("terminalProof",Map.of("type","FAILED_TERMINAL","reference","unique request failed permanently"));return engine.write(operation,args);}
    void cleanupFixture(){var prepared=call("action.prepare",Map.of("actionType","CREATE","target","owned","expectedEffect","one object","businessKey","owned-business-key","queryMethod","lookup"));resolve("action.resolve",prepared.get("actionId").toString(),"CONFIRMED_EFFECT");var rules=Map.of("CREATE",Map.of("effect","CREATE","entity","fixture"),"DELETE",Map.of("effect","DELETE","entity","fixture"));var policy=store.data(jdbc.queryForMap("SELECT * FROM msp_protocol_policy"));policy.put("allowedActions",List.of("CREATE","DELETE"));policy.put("actionRules",rules);jdbc.update("UPDATE msp_protocol_policy SET payload=?",store.payload(policy));jdbc.update("UPDATE msp_protocol_authorization SET payload=?",store.payload(Map.of("allowedActions",List.of("CREATE","DELETE"))));var session=store.data(jdbc.queryForMap("SELECT * FROM msp_protocol_session"));session.put("authorization",Map.of("actionRules",rules));jdbc.update("UPDATE msp_protocol_session SET payload=?",store.payload(session));updateData(data->{var contract=AgentProtocolData.object(data.get("contract"));contract.put("allowedActions",List.of("CREATE","DELETE"));data.put("contract",contract);data.put("syncStatus","SYNCED");});jdbc.update("UPDATE msp_protocol_instance SET phase='ENDED',channel='CLOSED',verification='ACCEPTED',result='PASS',result_version=1,revision=1");}
    Map<String,Object> deleteArgs(String object){return new LinkedHashMap<>(Map.of("actionType","DELETE","targetEntity","fixture","objectId",object,"target","owned object","expectedEffect","delete only this object","businessKey","cleanup-owned","queryMethod","authoritative delete lookup","parameters",Map.of()));}
    @Test void cleanupFailureAndRetryHaveIndependentStateAndCannotAlterFormalVerdict(){cleanupFixture();secondEvidence();var originalActions=data().get("actions");var prepared=call("cleanup.prepare",deleteArgs("owned-object"));var failure=resolve("cleanup.resolve",prepared.get("actionId").toString(),"CONFIRMED_NO_EFFECT");assertEquals("CLEANUP_FAILED",AgentProtocolData.object(data().get("cleanup")).get("state"));assertEquals("PASS",jdbc.queryForObject("SELECT result FROM msp_protocol_instance",String.class));assertEquals("ACCEPTED",jdbc.queryForObject("SELECT verification FROM msp_protocol_instance",String.class));var recovery=call("cleanup.recovery.record",Map.of("failureEventId",failure.get("eventId"),"observation","new authority evidence","changedCondition","cleanup service is ready","proposedAction","retry same owned object deletion","expectedObservation","terminal deletion","evidence",List.of(Map.of("kind","PERSONAL","id","fresh"))));var retry=deleteArgs("owned-object");retry.put("retryOf",prepared.get("actionId"));retry.put("recoveryPermitId",recovery.get("recoveryPermitId"));var permitted=call("cleanup.prepare",retry);resolve("cleanup.resolve",permitted.get("actionId").toString(),"CONFIRMED_EFFECT");assertEquals("CLEANED",AgentProtocolData.object(data().get("cleanup")).get("state"));assertEquals(originalActions,data().get("actions"));assertEquals(1L,jdbc.queryForObject("SELECT result_version FROM msp_protocol_instance",Long.class));assertEquals("ENDED",jdbc.queryForObject("SELECT phase FROM msp_protocol_instance",String.class));assertThrows(MSException.class,()->call("cleanup.prepare",deleteArgs("owned-object")));}
    @Test void cleanupRejectsAnotherPersonsObjectAndPreservesExistingFacts(){cleanupFixture();assertEquals("PROTOCOL_DATA_SCOPE_DENIED",assertThrows(MSException.class,()->call("cleanup.prepare",deleteArgs("someone-elses-object"))).getMessage());assertFalse(data().containsKey("cleanup"));assertEquals("PASS",jdbc.queryForObject("SELECT result FROM msp_protocol_instance",String.class));}

    void sourceTaskLifecycleFixture(String result,String sync){
        for(String column:"current_execution_id VARCHAR(64), ADD status VARCHAR(32), ADD verdict VARCHAR(32), ADD verdict_reason VARCHAR(128), ADD success_count INT, ADD failed_count INT, ADD blocked_count INT, ADD skipped_count INT, ADD unexecuted_count INT, ADD writeback_status VARCHAR(32), ADD finished_at BIGINT, ADD update_time BIGINT, ADD version INT DEFAULT 0".split(", ADD "))jdbc.execute("ALTER TABLE ai_execution_task ADD "+column);jdbc.update("UPDATE ai_execution_task SET current_execution_id='attempt',status='RUNNING'");for(String column:"status VARCHAR(32), ADD writeback_status VARCHAR(32), ADD update_time BIGINT, ADD version INT DEFAULT 0".split(", ADD "))jdbc.execute("ALTER TABLE ai_execution_case ADD "+column);jdbc.update("UPDATE ai_execution_case SET status='PENDING'");jdbc.execute("CREATE TABLE ai_execution_attempt(id VARCHAR(64),task_id VARCHAR(64),status VARCHAR(32),finish_time BIGINT,update_time BIGINT,version INT)");jdbc.update("INSERT INTO ai_execution_attempt VALUES ('attempt','task','RUNNING',NULL,1,0)");jdbc.execute("CREATE TABLE functional_case(id VARCHAR(64),last_execute_result VARCHAR(32))");jdbc.update("INSERT INTO functional_case VALUES ('case','KEEP_FORMAL')");jdbc.update("UPDATE msp_protocol_session SET source_type='TASK',source_id='task',source_execution_id='attempt',state='CLOSING'");jdbc.update("UPDATE msp_protocol_instance SET source_case_id='source-case',phase='ENDED',channel='CLOSED',verification='ACCEPTED',result=?,result_version=1",result);updateData(value->value.put("syncStatus",sync));
    }
    @Test void acceptedExecutionErrorAggregatesAsAgentFailureWithoutChangingFormalCase(){sourceTaskLifecycleFixture("EXECUTION_ERROR","NOT_APPLICABLE");var lifecycle=new AgentProtocolTaskLifecycleService(jdbc,store);lifecycle.reconcile("session");assertEquals("FAILED",jdbc.queryForObject("SELECT status FROM ai_execution_task",String.class));assertEquals("AGENT_FAILED",jdbc.queryForObject("SELECT verdict FROM ai_execution_task",String.class));assertEquals("ERROR",jdbc.queryForObject("SELECT status FROM ai_execution_case",String.class));assertEquals("KEEP_FORMAL",jdbc.queryForObject("SELECT last_execute_result FROM functional_case",String.class));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM msp_protocol_publication",Integer.class));Long version=jdbc.queryForObject("SELECT version FROM ai_execution_task",Long.class);lifecycle.reconcile("session");assertEquals(version,jdbc.queryForObject("SELECT version FROM ai_execution_task",Long.class));}
    @Test void acceptedButUnsyncedCaseCannotFinalizeItsRealSourceTask(){sourceTaskLifecycleFixture("PASS","FAILED");new AgentProtocolTaskLifecycleService(jdbc,store).reconcile("session");assertEquals("RUNNING",jdbc.queryForObject("SELECT status FROM ai_execution_task",String.class));assertEquals("CLOSING",jdbc.queryForObject("SELECT state FROM msp_protocol_session",String.class));assertEquals("KEEP_FORMAL",jdbc.queryForObject("SELECT last_execute_result FROM functional_case",String.class));}

    @Test void pendingStepCorrectionCreatesANewRevisionAndPreservesOriginalFacts(){call("step.save",Map.of("stepId","S1","observation","original agent report","outcome","VIOLATED","evidence",List.of(Map.of("kind","PERSONAL","id","personal"))));submit("PASS");var args=new LinkedHashMap<String,Object>(Map.of("protocolVersion","1.0","idempotencyKey","correct-pending","sessionId","session","caseExecutionId","instance","expectedResultVersion",1,"submissionRevision",1,"assertions",List.of(),"correctedSteps",List.of(Map.of("stepId","S1","observation","new supported observation","outcome","SATISFIED","evidence",List.of(Map.of("kind","PERSONAL","id","personal"))))));engine.write("result.evidence.append",args);assertEquals("VIOLATED",AgentProtocolData.objects(data().get("steps")).getFirst().get("outcome"));assertEquals("SATISFIED",AgentProtocolData.effectiveSteps(data()).getFirst().get("outcome"));assertEquals(2L,jdbc.queryForObject("SELECT revision FROM msp_protocol_instance",Long.class));assertEquals("NEEDS_EVIDENCE",jdbc.queryForObject("SELECT verification FROM msp_protocol_instance",String.class));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM msp_protocol_publication",Integer.class));}

    Map<String,Object> substitutionProposal(boolean changedGoal){var old=Map.of("type","OPERATION","scope","test","preconditions","old conditions","inputs",Map.of(),"outputs",Map.of("id",Map.of("type","string")));updateData(value->value.put("knowledge",List.of(Map.of("knowledgeId","method","version",1,"snapshot",old))));var methods=(AgentKnowledgeService)ReflectionTestUtils.getField(engine,"knowledge");when(methods.fixed(eq("org"),eq("method"),eq(2L),any(AgentProtocolAccess.Actor.class),anyBoolean())).thenReturn(Map.of("type","OPERATION","scope","test","preconditions","current conditions","inputs",Map.of(),"outputs",Map.of("orderId",Map.of("type","string")),"safetyGeneration",1));var difference=new LinkedHashMap<String,Object>();for(String key:List.of("goal","expected","assertions","entryPoint","authorization","environment","dataScope","risk","irreversibleEffects"))difference.put(key,"UNCHANGED");if(changedGoal)difference.put("goal","CHANGED");difference.put("preconditions","COMPATIBLE_WITH_EVIDENCE");difference.put("outputs","LOSSLESS_WITH_EVIDENCE");difference.put("inputMapping",Map.of());difference.put("outputMapping",Map.of("id","orderId"));difference.put("evidence",List.of(Map.of("kind","PERSONAL","id","personal")));return engine.write("knowledge.substitution.propose",Map.of("protocolVersion","1.0","idempotencyKey","proposal","sessionId","session","caseExecutionId","instance","knowledgeId","method","oldVersion",1,"newVersion",2,"difference",difference));}
    Map<String,Object> confirmation(Map<String,Object> proposal){return Map.of("protocolVersion","1.0","idempotencyKey","confirm","sessionId","session","caseExecutionId","instance","knowledgeId","method","oldVersion",1,"newVersion",2,"proposalHash",proposal.get("proposalHash"),"reason","same business semantics, authority evidence checked");}
    @Test void equivalentKnowledgeReplacementStillRequiresFreshPreflightAndDoesNotResetBudgets(){var proposal=substitutionProposal(false);reviewer();var confirmed=engine.write("knowledge.substitution.confirm",confirmation(proposal));assertEquals(true,confirmed.get("requiresPreflight"));assertEquals(true,data().get("needsRevalidation"));assertEquals(2,AgentProtocolData.objects(data().get("knowledge")).getFirst().get("version"));assertEquals(1,AgentProtocolData.objects(data().get("knowledgeSegments")).size());current.set(actor);assertEquals("PROTOCOL_PREFLIGHT_REQUIRED",assertThrows(MSException.class,()->call("action.prepare",Map.of("actionType","CREATE","target","owned","expectedEffect","one","businessKey","one","queryMethod","authority"))).getMessage());assertEquals(0L,jdbc.queryForObject("SELECT recoveries_used FROM msp_protocol_instance",Long.class));}
    @Test void knowledgeReplacementCannotChangeBusinessGoalInTheSameInstance(){var proposal=substitutionProposal(true);reviewer();assertEquals("PROTOCOL_NEW_INSTANCE_REQUIRED",assertThrows(MSException.class,()->engine.write("knowledge.substitution.confirm",confirmation(proposal))).getMessage());assertEquals(1,AgentProtocolData.objects(data().get("knowledge")).getFirst().get("version"));assertFalse(data().containsKey("knowledgeSegments"));}
}
